function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.fillStyle = 'yellow';
  ctx.fill();
  ctx.stroke();

  // clouds
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i) * 50, 20, 0, 2 * Math.PI);
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.stroke();
  }

  // trees
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H - 50);
  ctx.lineTo(W / 2 - 100, H - 150);
  ctx.lineTo(W / 2 - 70, H - 200);
  ctx.lineTo(W / 2 - 100, H - 150);
  ctx.fillStyle = 'green';
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H - 50);
  ctx.lineTo(W / 2 + 100, H - 150);
  ctx.lineTo(W / 2 + 70, H - 200);
  ctx.lineTo(W / 2 + 100, H - 150);
  ctx.fillStyle = 'green';
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W / 2, H - 100, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2, H - 80);
  ctx.lineTo(W / 2, H - 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2, H - 60);
  ctx.lineTo(W / 2 - 20, H - 80);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2, H - 60);
  ctx.lineTo(W / 2 + 20, H - 80);
  ctx.stroke();

  ctx.restore();
}
